// fold_table.go holds the character tables shared by the Unicode middlewares (the
// logic lives in unicode.go): the code-point sets AD ignores or folds to a space,
// and the sort-key fold maps. Active Directory compares String(Unicode) values
// through a Windows LCMapStringEx sort key ([MS-ADTS] section 3.1.1.2.2.4 /
// section 6.5, [MS-UCODEREF]) at LCID 0409; these tables capture, for that
// comparison, which code points are ignored, which fold to a space, and which
// fold to another character.

package helpers

// IgnorableRunes are the 288 stripped code points that are also
// Default_Ignorable_Code_Point: invisible on the wire (zero-width joiners, bidi
// controls, variation selectors, combining grapheme joiner, Mongolian FVS).
var IgnorableRunes = ExpandRuneRanges([][2]rune{
	{0x00AD, 0x00AD}, {0x034F, 0x034F}, {0x061C, 0x061C}, {0x180B, 0x180D},
	{0x180F, 0x180F}, {0x200C, 0x200F}, {0x202A, 0x202E}, {0x2060, 0x2064},
	{0x2066, 0x206F}, {0xFE00, 0xFE0F}, {0xFEFF, 0xFEFF}, {0xE0100, 0xE01EF},
})

