// AltSpaceRunes are the Unicode space code points, other than U+0020, that AD
// folds to a single SPACE (they share U+0020's sort key) and are invisible: four
// Zs spaces and the Mongolian vowel separator.
var AltSpaceRunes = []rune{0x1680, 0x180E, 0x202F, 0x205F, 0x3000}

// VisibleAltSpaceRunes are further code points AD folds to a single SPACE (same
// sort key) that, unlike AltSpaceRunes, RENDER as a visible glyph - the Hebrew
// maqaf, Tibetan tsheg/head marks, and the Tifinagh separator. They match as a
// space while changing the displayed value, so they are opt-in. The Tibetan
// svasti signs U+0FD5-0FD8 also fold here but are excluded (for obvious reasons).
var VisibleAltSpaceRunes = []rune{
	0x05BE, 0x0F0B, 0x0F0C, 0x0FD0, 0x0FD1, 0x0FD2, 0x0FD3, 0x0FD4, 0x0FD9, 0x0FDA, 0x2D70,
}

